            <section class="sq-page-block sq-cart-section" draggable="true" data-sq-block data-sq-fluid data-sq-rows="12" data-section-id="checkout"><button class="sq-block-handle" type="button" aria-label="Drag checkout section"><?= ez_admin_icon('grip') ?></button><div data-sq-element data-sq-element-type="copy" data-layout-desktop="1,1,6,12" data-layout-tablet="1,1,12,5" data-layout-mobile="1,1,12,5"><span>Your basket</span><h2>One checkout for every product on the page.</h2><p>Customers can combine products, choose quantities, and pay once through Ezkart's secure checkout.</p></div><aside data-sq-element data-sq-element-type="checkout" data-layout-desktop="8,2,5,10" data-layout-tablet="1,6,12,7" data-layout-mobile="1,6,12,7"><small>Example basket</small><ul data-sq-basket-lines><li data-product-line="granola"><span>Granola Madu Nusantara</span><b>Rp58.000</b></li><li data-product-line="coffee"><span>Kopi Susu Concentrate</span><b>Rp79.000</b></li><li data-product-line="sambal"><span>Sambal Roa Signature</span><b>Rp46.000</b></li></ul><footer><span>Total</span><strong data-sq-basket-total>Rp183.000</strong></footer><button type="button">Continue to secure checkout</button><em><?= ez_admin_icon('shield') ?> Secure checkout powered by Ezkart</em></aside></section>
            <section class="sq-page-block sq-shipping-section" id="shipping" data-physical-only draggable="true" data-sq-block data-sq-fluid data-sq-rows="5" data-section-id="shipping"><button class="sq-block-handle" type="button" aria-label="Drag shipping section"><?= ez_admin_icon('grip') ?></button><span data-sq-element data-sq-element-type="icon" data-layout-desktop="1,1,1,5" data-layout-tablet="1,1,2,5" data-layout-mobile="1,1,2,5"><?= ez_admin_icon('truck') ?></span><div data-sq-element data-sq-element-type="copy" data-layout-desktop="2,1,7,5" data-layout-tablet="3,1,10,3" data-layout-mobile="3,1,10,3"><small>Ezkart fulfillment</small><h2>From page visit to delivered order.</h2><p>Address collection, product weights, courier quotes, payment state, and fulfillment stay connected in one flow.</p></div><ul data-sq-element data-sq-element-type="list" data-layout-desktop="9,1,4,5" data-layout-tablet="3,4,10,2" data-layout-mobile="3,4,10,2"><li>JNE REG</li><li>SiCepat REG</li><li>J&amp;T EZ</li></ul></section>
