<dialog class="sq-export-dialog" id="html-export-dialog">
  <form method="dialog"><header><span><?= ez_admin_icon('code') ?></span><div><small>Production output</small><h2>Generated landing-page HTML</h2><p>Responsive structure, selected products, spacing, animations, SEO metadata, and checkout hooks are included.</p></div><button value="close" aria-label="Close HTML export"><?= ez_admin_icon('x') ?></button></header><div class="sq-export-summary"><span><?= ez_admin_icon('check-circle') ?> Semantic HTML</span><span><?= ez_admin_icon('check-circle') ?> Responsive CSS</span><span><?= ez_admin_icon('check-circle') ?> Animation CSS</span><span><?= ez_admin_icon('check-circle') ?> Commerce hooks</span></div><textarea readonly spellcheck="false" data-sq-html-output></textarea><footer><small data-sq-html-size>Ready to generate</small><button type="button" data-sq-copy-html>Copy HTML</button><button class="primary" type="button" data-sq-download-html><?= ez_admin_icon('download') ?> Download .html</button></footer></form>
</dialog>

<dialog class="page-creator-dialog" id="page-creator-dialog"><form method="dialog" data-page-creator-form>
  <header><span><?= ez_admin_icon('layout') ?></span><div><small>Create a landing page</small><h2>Start with at least one product.</h2><p>Choose from the real products already saved in your Ezkart catalog.</p></div><button type="button" data-creator-close aria-label="Close"><?= ez_admin_icon('x') ?></button></header>
  <section>
    <label><span>Page name</span><input name="page_name" required maxlength="60" placeholder="Example: Ramadan Collection"></label>
    <fieldset data-creator-products><legend>Starting products</legend><p class="creator-products-empty" data-creator-products-empty>No products are available yet. <a href="?page=products">Create a product first</a>.</p></fieldset>
    <label><span>Free Ezkart URL</span><div class="slug-field"><input name="slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="ramadan-collection"><em>.ezkart.site</em></div></label>
  </section>
  <footer><button type="button" data-creator-close>Cancel</button><button class="primary" value="default" data-create-page>Build full page</button></footer>
</form></dialog>
